-- ============================================================================
-- 257 — تعديل القانون رقم 3 لسنة 2005 (حماية المنافسة ومنع الممارسات الاحتكارية) بالقانون رقم 175 لسنة 2022 (الرقابة على التركز الاقتصادى)
-- ----------------------------------------------------------------------------
-- المصدر: ملف PDF من 10 صفحات (بلا طبقة نص) قدمه المالك: الجريدة الرسمية - العدد 52 تابع (أ) فى 29 ديسمبر سنة 2022 (الصفحات 3 إلى 12): القانون 175 لسنة 2022 بتعديل بعض أحكام قانون حماية المنافسة. قُرئت الصفحات العشر بصرياً كلها وكُبّرت الأرقام والمبالغ والمدد (900 مليون، 200 مليون، 7.5 مليار، 100 ألف، 30 و60 و15 يوم عمل، 1% و10%، 30 و500 مليون) وروجعت. الإملاء كما طُبع (مثل «موردية» فى م19 مكرراً بند 3).
-- نطاق التعديل: المادة الأولى تستبدل البند (2) من م11 والمادة 18 والفقرة الأولى من م20؛ المادة الثانية تضيف تعريفات (ز، ح، ط، ى، ك) إلى م2، والمواد 19 مكرراً و19 مكرراً (أ، ب، ج، د، هـ، و) (نظام الإخطار بالتركز الاقتصادى وفحصه)، والمادة 22 مكرراً (د) (غرامات التركز)؛ المادة الثالثة تلغى الفقرة الثانية من م19 والبند 1 من م22 مكرراً (وكلاهما من إضافات القانون 190/2008)؛ المادة الرابعة النشر والعمل من اليوم التالى للنشر.
-- التواريخ: النشر 2022-12-29 فالعمل من 2022-12-30. النسخة السارية قبله تُغلق بـ effective_to = 2022-12-29 كى تبقى استعلامات النص الحالى (effective_to IS NULL) على النسخة الجديدة وحدها.
-- التمثيل (نمط REPLACE): المواد 2 و11 و18 و19 و20 و22 مكرراً (suffix 1) تحمل نسخة جديدة بعد الحالية؛ الثمانى المواد الجديدة بنسخة واحدة: 19 مكرراً (suffix 1) ثم أ..و (2 إلى 7) على ترتيب المشروع (مكرراً=1، (أ)=2 ...)، و22 مكرراً (د) suffix 5 (3 و4 محجوزان لـ(ب) و(ج)).
-- تنبيهات: (1) م2: الحروف الجديدة ز..ك توحى بوجود (هـ) و(و) غير موجودين فى النص الأصلى المخزن (4 بنود فقط)؛ لم يُضف شىء لهما ويلزم تحقق من الأصل. (2) م22 مكرراً (ب) و(ج) غير موجودتين فى القاعدة؛ تسمية (د) توحى بوجودهما. (3) م11 بند 2 استُبدل بالكامل فسقطت فقرته الثانية (ميعاد وبيانات الإخطار) تفسيراً لعبارة «استبدال البند (2)». (4) م22 مكرراً: بقى البند 2 بترقيمه المطبوع بلا إعادة ترقيم. (5) الواردات التى تحيل إليها المواد الجديدة للائحة التنفيذية، ولائحة القانون غير مضافة. (6) المواد المعدلة والجديدة بلا embedding فتحتاج إعادة تضمين.
-- الطريقة: ترفض التشغيل إن لم يوجد القانون 3/2005 أو إن اختلف نص أى مادة معدلة عن نص ما بعد 225 و256؛ قابلة لإعادة التشغيل (تتخطى ما طُبق) وتبقى سليمة بعد أى تعديلات لاحقة على نفس المواد. ولا تمس أى قانون آخر.
-- ============================================================================

CREATE TEMP TABLE m257_amend (
  article_no int NOT NULL, suffix int NOT NULL, loc text NOT NULL, pre_md5 text NOT NULL, new_body text NOT NULL, new_md5 text NOT NULL, note text NOT NULL
) ON COMMIT DROP;
CREATE TEMP TABLE m257_new (
  article_no int NOT NULL, suffix int NOT NULL, loc text NOT NULL, body text NOT NULL, body_md5 text NOT NULL, note text NOT NULL
) ON COMMIT DROP;

INSERT INTO m257_amend VALUES
(2,0,$l257$المادة 2$l257$,'b5506244fbf54faeee7948fac0b43f40',$n257$فى تطبيق أحكام هذا القانون يقصد بالكلمات الآتية المعنى المبين قرين كل منها :
( أ ) الأشخاص : الأشخاص الطبيعيون والأشخاص الاعتبارية ، والكيانات الاقتصادية ، والاتحادات ، والروابط والتجمعات المالية وتجمعات الأشخاص على اختلاف طرق تأسيسها ، وغيرها من الأطراف المرتبطة على النحو الذى تحدده اللائحة التنفيذية بما يتفق مع أهداف وأحكام هذا القانون .
( ب ) المنتجات : السلع والخدمات .
( جـ ) الجهاز : جهاز حماية المنافسة ومنع الممارسات الاحتكارية المنشأ طبقًا لأحكام هذا القانون .
( د ) المجلس : مجلس إدارة جهاز حماية المنافسة ومنع الممارسات الاحتكارية .
( ز ) التركز الاقتصادى : هو كل تغيير فى التحكم أو التأثير المادى فى شخص أو عدة أشخاص ، والذى يكون ناتجاً عن أى من الحالات الآتية :
1 - اندماج شخص أو أكثر فى شخص قائم يحتفظ بشخصيته القانونية عقب الاندماج ، أو إنشاء شخص جديد عن طريق مزج اثنين على الأقل من الأشخاص ، التى كانت مستقلة سابقاً ، وانقضاء شخصيتها القانونية أو أى من أجزائها .
2 - استحواذ شخص أو أكثر ، بطريقة مباشرة أو غير مباشرة ، على التحكم أو التأثير المادى فى شخص آخر أو جزء منه بموجب عقد ، أو عن طريق شراء أوراق مالية أو أصول أو غيرها من الطرق ، ويمكن أن يتم الاستحواذ بشكل فردى أو جماعى .
3 - إنشاء مشروع مشترك أو استحواذ شخصين أو أكثر على شخص قائم بغرض إنشاء مشروع مشترك يمارس نشاطاً اقتصادياً بشكل مستقل ودائم .
ولا يعد تركزاً اقتصادياً أى من الحالات الآتية :
1 - استحواذ أى من الشركات العاملة فى مجال الأوراق المالية بصفة مؤقتة على أوراق مالية فى أحد الأشخاص بغرض إعادة بيعها فى غضون عام من تاريخ الاستحواذ ، شريطة عدم ممارستها لأى من حقوق التصويت أو اتخاذ أى إجراء أو تدبير يكون من شأنه التأثير على القرارات الاستراتيجية أو الأهداف التجارية للشخص المستحوذ عليه ، ويجوز للجهاز مد هذه المدة عند الطلب إذا أثبت المستحوذ عدم إمكانية إعادة بيع الأوراق المالية فى غضون عام ، وذلك على النحو الذى تحدده اللائحة التنفيذية لهذا القانون .
2 - حدوث اندماج أو استحواذ بين شركات تابعة لنفس الشخص ، وتعد هذه العملية من قبيل إعادة الهيكلة ، ولا ينشأ الالتزام بالإخطار إلا فى حالة وجود تغير فى التحكم والتأثير المادى بطريق مباشر أو غير مباشر .
( ح ) التحكم : هو قدرة الشخص أو الأشخاص المتحكمة فى ممارسة تأثير فعال ، بشكل مباشر أو غير مباشر ، عن طريق توجيه القرارات الاقتصادية لشخص أو أشخاص آخرين ، إما استناداً إلى الأغلبية فى حقوق التصويت أو إلى قدرة الشخص المتحكم على الحيلولة دون اتخاذ قرارات اقتصادية خاصة بالشخص أو بالأشخاص الآخرين ، أو أية طريقة أخرى ، ويشمل ذلك كل وضع أو اتفاق أو ملكية لأسهم أو حصص أياً كانت نسبتها ، بشرط أن يؤدى إلى التحكم الفعلى فى الإدارة أو فى اتخاذ القرارات .
( ط ) التأثير المادى : هو القدرة على التأثير بشكل مباشر أو غير مباشر على سياسة شخص آخر ، بما فى ذلك قراراته الاستراتيجية أو أهدافه التجارية على النحو الذى تحدده اللائحة التنفيذية لهذا القانون .
( ى ) التدابير التصحيحية : هى مجموعة التدابير السلوكية أو الهيكلية التى تهدف إلى إزالة الآثار الضارة بالمنافسة الناتجة عن تنفيذ التركز الاقتصادى .
( ك ) التدابير السلوكية : هى التدابير التى تلزم الأشخاص المعنية بالتركز الاقتصادى بالالتزام أو الامتناع عن القيام ببعض الأعمال والأفعال .$n257$,'02101559273fdcc69b7d10ecb027b595',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) أضاف إلى المادة 2 خمسة تعريفات جديدة هى (ز) التركز الاقتصادى و(ح) التحكم و(ط) التأثير المادى و(ى) التدابير التصحيحية و(ك) التدابير السلوكية بعد البند (د). البنود (أ) إلى (د) دون تغيير. تنبيه: النص المنشور يسمى البنود الجديدة ز..ك مما يوحى بوجود بندين (هـ) و(و) لا يظهران فى النص الأصلى المخزن؛ لم يُضف شىء لهما.$c257$),
(11,0,$l257$المادة 11$l257$,'43f2762f9c8a92bd6d0efce3ffb0b48a',$n257$ينشأ جهاز يسمى جهاز حماية المنافسة ومنع الممارسات الاحتكارية يكون مقره القاهرة الكبرى وتكون له الشخصية الاعتبارية العامة ، يتبع الوزير المختص ، ويتولى على الأخص ما يلى :
( 1 ) تلقى الطلبات باتخاذ إجراءات التقصى والبحث وجمع الاستدلالات والأمر باتخاذ هذه الإجراءات بالنسبة لحالات الاتفاقات والممارسات الضارة بالمنافسة ، وذلك طبقاً للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
( 2 ) فحص البلاغات المنصوص عليها فى المادة ( 19 ) من هذا القانون ، والإخطارات المشار إليها فى المادتين ( 19 مكرراً أ ، 19 مكرراً هـ ) من هذا القانون .
( 3 ) إعداد قاعدة بيانات ومعلومات متكاملة عن النشاط الاقتصادى وتحديثها وتطويرها بصورة دائمة بما يخدم عمل الجهاز فى كافة المجالات المرتبطة بحماية المنافسة .
وإنشاء قاعدة بيانات وإجراء الدراسات والبحوث اللازمة لكشف الحالات الضارة بالمنافسة .
( 4 ) اتخاذ التدابير المنصوص عليها فى المادة ( 20 ) من هذا القانون .
( 5 ) إبداء الرأى فى مشروعات القوانين واللوائح المتعلقة بتنظيم المنافسة .
( 6 ) التنسيق مع الأجهزة النظيرة فى الدول الأخرى بالنسبة للأمور ذات الاهتمام المشترك .
( 7 ) تنظيم برامج تدريبية وتثقيفية بهدف التوعية بأحكام هذا القانون ومبادئ السوق الحرة بوجه عام .
( 8 ) إصدار نشرة دورية تتضمن القرارات والتوصيات والإجراءات والتدابير التى يتخذها الجهاز وغير ذلك مما يتصل بشئونه .
( 9 ) إعداد تقرير سنوى عن أنشطة الجهاز وخطته المستقبلية ومقترحاته ليعرض على الوزير المختص بعد اعتماده من مجلس الإدارة ، وترسل نسخة منه إلى مجلسى الشعب والشورى .
وتحدد اللائحة التنفيذية لهذا القانون الإجراءات التى يتبعها الجهاز لتحقيق وإثبات الأفعال التى تتضمن أو تشكل مخالفة لأحكام هذا القانون .
ويلتزم الأشخاص بموافاة الجهاز بما يطلبه من البيانات أو الأوراق أو المستندات اللازمة لممارسة اختصاصاته وذلك خلال المواعيد التى يحددها .$n257$,'d87c668a3ec28c0c9c4b1e8941f19fb9',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) استبدل البند (2) من المادة 11 بالكامل فصار «فحص البلاغات المنصوص عليها فى المادة 19 والإخطارات المشار إليها فى المادتين 19 مكرراً أ و19 مكرراً هـ». سقطت بذلك فقرته الثانية (ميعاد وبيانات الإخطار) لأن النص البديل لا يتضمنها. باقى البنود والفقرة الثالثة المضافة بالقانون 190/2008 دون تغيير.$c257$),
(18,0,$l257$المادة 18$l257$,'c900a866b8e4fc4efe46baf24906e260',$n257$تحدد فئات الرسوم التى يستحقها الجهاز مقابل فحص ملفات الإخطار بالتركز الاقتصادى المنصوص عليه فى المادتين ( 19 مكرراً أ ، 19 مكرراً هـ ) من هذا القانون بما لا يجاوز مائة ألف جنيه على أن يتحمل مقدم الطلب تكاليف النشر ، كما تحدد فئات الرسوم التى يستحقها الجهاز مقابل الاطلاع والحصول على المستندات وفحص الطلبات المنصوص عليها فى الفقرة الثانية من كل من المادتين ( 6 ، 9 ) من هذا القانون بما لا يجاوز عشرة آلاف جنيه ، وذلك كله على النحو الذى تحدده اللائحة التنفيذية لهذا القانون .
ويقوم الجهاز بتحصيل الرسوم المشار إليها بإحدى وسائل الدفع المنصوص عليها فى قانون تنظيم استخدام وسائل الدفع غير النقدى الصادر بالقانون رقم 18 لسنة 2019 .$n257$,'f9555b149f814026303cfc0fdf69734b',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) استبدل المادة 18 بالكامل: رسم فحص ملفات الإخطار بالتركز الاقتصادى بما لا يجاوز مائة ألف جنيه (على أن يتحمل مقدم الطلب تكاليف النشر)، ورسم الاطلاع والحصول على المستندات وفحص الطلبات بما لا يجاوز عشرة آلاف جنيه، وتحصيلها بوسائل الدفع غير النقدى (القانون 18/2019).$c257$),
(19,0,$l257$المادة 19$l257$,'543ccb51104911b80d0ac9208bfa0709',$n257$يجوز لأى شخص إبلاغ الجهاز بأية مخالفة تقع لأحكام هذا القانون .$n257$,'31ca95c46212e1a4e5257a7619e875c9',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) ألغى الفقرة الثانية من المادة 19 (إخطار من يتجاوز رقم أعماله مائة مليون جنيه) التى كان أضافها القانون 190/2008، وحل محلها نظام الإخطار بالتركز الاقتصادى فى المواد 19 مكرراً إلى 19 مكرراً و.$c257$),
(20,0,$l257$المادة 20$l257$,'727b54858a5e53bbed0bcc442c443164',$n257$على الجهاز عند ثبوت مخالفة أى من أحكام المواد ( 6 ، 7 ، 8 ، 19 مكرراً أ ، 19 مكرراً ج ، 19 مكرراً د ) من هذا القانون ، تكليف المخالف بتعديل أوضاعه وإزالة المخالفة أو اتخاذ تدابير تصحيحية فوراً أو خلال فترة زمنية يحددها المجلس ، وإلا وقع الاتفاق أو التعاقد المخالف باطلاً .
وللمجلس أن يصدر قراراً بوقف الممارسات المحظورة فوراً ، أو بعد انقضاء الفترة الزمنية المشار إليها دون تعديل الأوضاع وإزالة المخالفة .
وذلك كله دون الإخلال بأحكام المسئولية الناشئة عن هذه المخالفات .$n257$,'8225c8c3a3f43ff0ab077387acc8ae12',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) استبدل الفقرة الأولى من المادة 20: أُضيفت المواد 19 مكرراً أ و19 مكرراً ج و19 مكرراً د إلى المواد التى يكلف الجهاز المخالف بتعديل أوضاعه عند مخالفتها، وأُضيفت «اتخاذ تدابير تصحيحية». باقى فقرات المادة دون تغيير.$c257$),
(22,1,$l257$المادة 22 مكرراً$l257$,'425989975f160481edd2b0ceb8e5e52f',$n257$يعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز مائة ألف جنيه كل من :
2 - امتنع عن موافاة الجهاز بالبيانات أو الأوراق أو المستندات المنصوص عليها فى الفقرة الثالثة من المادة ( 11 ) من هذا القانون .
ومع عدم الإخلال بأية عقوبة أشد تكون العقوبة الغرامة التى لا تقل عن عشرين ألف جنيه ولا تجاوز مائتى ألف جنيه فى حالة إمداد الجهاز ببيانات أو أوراق أو مستندات غير صحيحة مع العلم بذلك .$n257$,'96d9ced1d39fcb93ba4b25c9b3f2acab',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) ألغى البند 1 من المادة 22 مكرراً (غرامة الإخلال بواجب الإخطار وفق الفقرة الثانية من م19) لإلغاء تلك الفقرة. بقى البند 2 بترقيمه المطبوع (2) دون إعادة ترقيم لأن القانون لم ينص على إعادة الترقيم.$c257$);

INSERT INTO m257_new VALUES
(19,1,$l257$المادة 19 مكرراً$l257$,$n257$يخضع التركز الاقتصادى لفحص الجهاز إذا توافرت فيه أى من الحدود الآتية :
( أ ) تجاوز رقم الأعمال السنوى المحقق أو الأصول المجمعة فى مصر للأشخاص المعنية مجتمعة مبلغ تسعمائة مليون جنيه مصرى عن آخر سنة فى آخر قوائم مالية مجمعة معتمدة ، وبشرط تجاوز رقم الأعمال السنوى فى مصر لشخصين على الأقل من الأشخاص المعنية ولكل منهما على حدة مبلغ مائتى مليون جنيه مصرى عن آخر سنة فى آخر قوائم مالية مجمعة معتمدة .
( ب ) تجاوز رقم الأعمال السنوى المحقق أو الأصول المجمعة على مستوى العالم للأشخاص المعنية مجتمعة مبلغ سبعة مليارات وخمسمائة مليون جنيه مصرى عن آخر سنة فى آخر قوائم مالية مجمعة معتمدة ، وبشرط تجاوز رقم الأعمال السنوى فى مصر لشخص على الأقل من الأشخاص المعنية فى آخر قوائم مالية مجمعة معتمدة مبلغ مائتى مليون جنيه مصرى .
وتبين اللائحة التنفيذية لهذا القانون طريقة حساب رقم الأعمال السنوى والأصول المجمعة .
وفى جميع الأحوال ، يحق للجهاز بناءً على موافقة المجلس بدء فحص التركز الاقتصادى الذى لا يجاوز الحدود المبينة لواجب الإخطار إذا قامت لديه أدلة أو قرائن من شأنها الحد من حرية المنافسة أو تقييدها أو الإضرار بها خلال فترة لا تجاوز سنة من تاريخ تنفيذ التركز الاقتصادى على النحو المحدد فى اللائحة التنفيذية لهذا القانون .
وللمجلس فى حالة ثبوت الحد من حرية المنافسة أو تقييدها أو الإضرار بها فرض تدبير أو أكثر من التدابير السلوكية التالية التى من شأنها الحد من الآثار الضارة على المنافسة للتركز الاقتصادى ، بحسب الأحوال :
1 - الامتناع عن القيام بفعل من شأنه أن يؤدى إلى الاقتصار على توزيع منتج دون غيره .
2 - إتاحة المرافق أو الخدمات الأساسية للأشخاص المتنافسة .
3 - الامتناع عن التمييز فى الاتفاقات أو التعاقدات أياً كان نوعها التى يبرمها مع موردية أو مع عملائه متى تشابهت مراكزهم التعاقدية سواء كان هذا التمييز فى الأسعار أو نوعية المنتجات أو فى شروط التعامل الأخرى .
4 - الامتناع عن تعليق إبرام عقد أو اتفاق خاص بمنتج على شرط قبول التزامات أو منتجات تكون بطبيعتها أو بموجب الاستخدام التجارى لها غير مرتبطة بالمنتج محل الاتفاق أو التعاقد أو التعامل الأصلى .
وتتمثل القرائن المشار إليها فى تحقق صورة أو أكثر من الصور الآتية :
الحد من التطور التكنولوجى والابتكار .
التحكم فى السوق بزيادة أو خفض الأسعار .
تقليل جودة المنتجات .
خلق عوائق الدخول أو التوسع فى السوق .$n257$,'3aebe94452b289f3e2ddaa223501c086',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) مادة مضافة بالمادة الثانية من القانون. المادة تحمل ترتيب suffix=1؛ المواد المجاورة (22 مكرراً (ب) و(ج) المفترضة من تسمية (د)) غير موجودة فى القاعدة.$c257$),
(19,2,$l257$المادة 19 مكرراً (أ)$l257$,$n257$يجب إخطار الجهاز بأى تركز اقتصادى يستوفى الشروط الموضحة فى المادة ( 19 مكرراً ) من هذا القانون ، ولا يجوز تنفيذ التركز الاقتصادى قبل الحصول على موافقة الجهاز .
ولا يخل الالتزام بالإخطار المشار إليه فى الفقرة الأولى من هذه المادة بواجب الإخطار المنصوص عليه فى أى قانون آخر أو فى الاتفاقيات الدولية التى تكون جمهورية مصر العربية طرفاً فيها .$n257$,'20633c177ebca9239771cb47d6be1120',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) مادة مضافة بالمادة الثانية من القانون. المادة تحمل ترتيب suffix=2؛ المواد المجاورة (22 مكرراً (ب) و(ج) المفترضة من تسمية (د)) غير موجودة فى القاعدة.$c257$),
(19,3,$l257$المادة 19 مكرراً (ب)$l257$,$n257$يحظر التركز الاقتصادى إذا كان من شأنه الحد من حرية المنافسة أو تقييدها أو الإضرار بها ، وتبين اللائحة التنفيذية العناصر التى تؤخذ فى الاعتبار عند تقييم آثار التركز الاقتصادى على حرية المنافسة فى السوق .
ويجوز للجهاز بعد موافقة مجلس الوزراء التصريح بإجراء التركز الاقتصادى إذا كان من شأن عدم تنفيذه خروج أشخاص من السوق ، أو إذا ثبت أن التركز الاقتصادى سينتج عنه كفاءة اقتصادية تفوق آثار الحد من المنافسة أو تحقيق اعتبارات تتعلق بحماية الأمن القومى ، وذلك حال توافر الشروط التى تحددها اللائحة التنفيذية لهذا القانون .$n257$,'f940b5ccbf1b7b1965b4f850742f7502',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) مادة مضافة بالمادة الثانية من القانون. المادة تحمل ترتيب suffix=3؛ المواد المجاورة (22 مكرراً (ب) و(ج) المفترضة من تسمية (د)) غير موجودة فى القاعدة.$c257$),
(19,4,$l257$المادة 19 مكرراً (ج)$l257$,$n257$يتولى الجهاز فحص التركز الاقتصادى فى مرحلة الفحص الأولى خلال ثلاثين يوم عمل تبدأ من يوم العمل التالى لتاريخ إيداع ملف الإخطار المنصوص عليه فى المادة ( 19 مكرراً أ ) من هذا القانون كاملاً ، لبيان إذا ما كان يشكل أيا من القيود الواردة فى المادة ( 19 مكرراً ب ) من هذا القانون ، ويجوز مد هذه المدة خمسة عشر يوم عمل فى حالة تقديم عرض التزامات وضوابط من الأشخاص على النحو الذى تحدده اللائحة التنفيذية لهذا القانون .
ويصدر المجلس قراراً بتشكيل لجان فحص تشكل كل منها من ثلاثة من أعضائه ، وتجتمع هذه اللجان بدعوة من رئيسها ، وتتخذ قراراتها بأغلبية أعضائها ، ويجوز لها الاستعانة بمن تراه من الخبراء دون أن يكون له الحق فى التصويت .
وتصدر لجان الفحص المشار إليها فى الفقرة الثانية من هذه المادة أحد القرارات الآتية :
1 - عدم اختصاص الجهاز بنظر ملف الإخطار .
2 - حفظ الطلب : فى حالة عدول الأشخاص عن تنفيذ التركز الاقتصادى .
3 - الموافقة : إذا كان التركز الاقتصادى المخطر به يتوافق مع المادة ( 19 مكرراً ب ) من هذا القانون .
4 - الموافقة المشروطة : إذا أصبح التركز الاقتصادى متوافقاً مع المادة ( 19 مكرراً ب ) من هذا القانون بعد الموافقة على عرض الالتزامات والضوابط المقدم من الأشخاص .
5 - الإحالة لمرحلة الفحص الثانية : إذا كان التركز الاقتصادى يثير شبهة الحد من حرية المنافسة أو تقييدها أو الإضرار بها .
وإذا انقضت المدة المحددة فى الفقرة الأولى من هذه المادة دون صدور قرار اعتبر ذلك بمثابة موافقة على التركز الاقتصادى .$n257$,'b2a03281bf19adbb3ff55e4a86f4358e',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) مادة مضافة بالمادة الثانية من القانون. المادة تحمل ترتيب suffix=4؛ المواد المجاورة (22 مكرراً (ب) و(ج) المفترضة من تسمية (د)) غير موجودة فى القاعدة.$c257$),
(19,5,$l257$المادة 19 مكرراً (د)$l257$,$n257$يستمر الجهاز فى فحص ملف الإخطار خلال ستين يوم عمل تبدأ من تاريخ صدور قرار من إحدى لجان الفحص بإحالة ملف الإخطار إلى مرحلة الفحص الثانية ، ويجوز مد هذه المدة خمسة عشر يوم عمل فى حالة تقديم عرض التزامات وضوابط من الأشخاص ، وذلك على النحو الذى تحدده اللائحة التنفيذية لهذا القانون .
فإذا انقضت المدة المحددة فى الفقرة الأولى من هذه المادة دون صدور قرار اعتبر ذلك بمثابة موافقة على تنفيذ التركز الاقتصادى .
ويصدر المجلس ، بعد انتهاء مرحلة الفحص الثانية ، أحد القرارات الآتية :
1 - حفظ الطلب : فى حالة عدول الأشخاص عن تنفيذ التركز الاقتصادى .
2 - الموافقة فى حالة إذا ما كان التركز الاقتصادى المخطر به يتوافق مع المادة ( 19 مكرراً ب ) من هذا القانون .
3 - الموافقة المشروطة : إذا أصبح التركز الاقتصادى متوافقاً مع المادة ( 19 مكرراً ب ) من هذا القانون بعد الموافقة على عرض الالتزامات والضوابط المقدم من الأشخاص .
4 - الرفض : إذا كان من شأن التركز الاقتصادى الحد من حرية المنافسة أو تقييدها أو الإضرار بها ، ويجوز التظلم من قرار الرفض خلال ثلاثين يوماً من تاريخ إخطار الأشخاص به .$n257$,'e1f8c6010607e659deb97a416e15b578',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) مادة مضافة بالمادة الثانية من القانون. المادة تحمل ترتيب suffix=5؛ المواد المجاورة (22 مكرراً (ب) و(ج) المفترضة من تسمية (د)) غير موجودة فى القاعدة.$c257$),
(19,6,$l257$المادة 19 مكرراً (هـ)$l257$,$n257$لا تسرى أحكام المواد ( 19 مكرراً أ ، 19 مكرراً ج ، 19 مكرراً د ، 20 ، 22 ، 22 مكرراً د ) من هذا القانون على التركزات الاقتصادية التى تتم فى أى من الأنشطة الخاضعة لإشراف ورقابة الهيئة العامة للرقابة المالية .
ويلتزم الأشخاص بإخطار الهيئة العامة للرقابة المالية بالتركز الاقتصادى المشار إليه فى الفقرة الأولى من هذه المادة قبل إبرام العقد ، وعلى الهيئة استطلاع رأى الجهاز قبل الموافقة على تنفيذ التركز الاقتصادى .
ويتولى الجهاز فحص التركز الاقتصادى وفقاً للإجراءات والمواعيد المنصوص عليها فى المادة ( 19 مكرراً و ) من هذا القانون .$n257$,'8d0a1ed138d1de3b5260bbf7f6bc1a3c',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) مادة مضافة بالمادة الثانية من القانون. المادة تحمل ترتيب suffix=6؛ المواد المجاورة (22 مكرراً (ب) و(ج) المفترضة من تسمية (د)) غير موجودة فى القاعدة.$c257$),
(19,7,$l257$المادة 19 مكرراً (و)$l257$,$n257$يتولى الجهاز فحص التركزات الاقتصادية المشار إليها فى المادة ( 19 مكرراً هـ ) من هذا القانون خلال ثلاثين يوماً تبدأ من اليوم التالى لتاريخ ورود ملف الإخطار كاملاً من الهيئة العامة للرقابة المالية ، لبيان إذا ما كان يشكل أيا من القيود الواردة فى المادة ( 19 مكرراً ب ) من هذا القانون .
ويصدر المجلس قراراً بتشكيل لجان فحص تشكل من ثلاثة من أعضائه ، وتجتمع هذه اللجان بدعوة من رئيسها ، وتتخذ قراراتها بأغلبية أعضائها ، ويجوز لها الاستعانة بمن تراه من الخبراء دون أن يكون له الحق فى التصويت .
وتصدر لجان الفحص المشار إليها فى الفقرة الثانية من هذه المادة أحد القرارات الآتية :
1 - عدم اختصاص الجهاز بنظر ملف الإخطار .
2 - حفظ الطلب : فى حالة عدول الأشخاص المعنية عن تنفيذ التركز الاقتصادى أو عدم تقديم البيانات والمعلومات والمستندات المطلوبة فى المواعيد المحددة من قبل الجهاز .
3 - توصية بالموافقة : إذا كان التركز الاقتصادى المخطر به يتوافق مع نص المادة ( 19 مكرراً ب ) من هذا القانون .
4 - توصية بالرفض : إذا كان من شأن التركز الاقتصادى الحد من حرية المنافسة أو تقييدها أو الإضرار بها .
وفى حالة انقضاء المدة المحددة فى الفقرة الأولى من هذه المادة دون رد من الجهاز اعتبر ذلك بمثابة عدم ممانعة على تنفيذ التركز الاقتصادى .$n257$,'48b072f16651965508f4738a2134a6dc',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) مادة مضافة بالمادة الثانية من القانون. المادة تحمل ترتيب suffix=7؛ المواد المجاورة (22 مكرراً (ب) و(ج) المفترضة من تسمية (د)) غير موجودة فى القاعدة.$c257$),
(22,5,$l257$المادة 22 مكرراً (د)$l257$,$n257$يعاقب بغرامة لا تقل عن ( 1% ) ولا تجاوز ( 10% ) من إجمالى رقم الأعمال السنوى أو الأصول أو قيمة العملية للأشخاص محل التركز الاقتصادى أيهما أعلى ، طبقاً لآخر ميزانية مجمعة معتمدة للأشخاص ، وفى حالة تعذر حساب تلك النسبة تكون العقوبة غرامة لا تقل عن ثلاثين مليون جنيه ولا تجاوز خمسمائة مليون جنيه مصرى ، كل من ارتكب أيا من الآتى :
أولاً - أخل بالتزام الإخطار المنصوص عليه فى المادتين ( 19 مكرراً أ ، 19 مكرراً هـ ) من هذا القانون .
ثانياً - خالف قرار الموافقة المشروطة طبقاً لأى من المادتين ( 19 مكرراً ج ، 19 مكرراً د ) من هذا القانون .
ثالثاً - خالف قرار رفض تنفيذ التركز الاقتصادى طبقاً للمادة ( 19 مكرراً د ) من هذا القانون .
رابعاً - حصل على قرار بالموافقة على تنفيذ التركز الاقتصادى طبقاً لأى من المادتين ( 19 مكرراً ج أو 19 مكرراً د ) من هذا القانون بناء على تقديم بيانات أو معلومات أو مستندات غير صحيحة مع علمه بذلك .
خامساً - حصل على موافقة الهيئة العامة للرقابة المالية على تنفيذ التركز الاقتصادى المشار إليه فى المادة ( 19 مكرراً هـ ) من هذا القانون ، بناء على تقديم بيانات أو معلومات أو مستندات غير صحيحة للجهاز مع علمه بذلك .$n257$,'2c67c7c3117bffdcc07f0fb090f2e3e6',$c257$القانون 175 لسنة 2022 (الجريدة الرسمية العدد 52 تابع (أ) فى 29/12/2022؛ العمل به من 30/12/2022) مادة مضافة بالمادة الثانية من القانون. المادة تحمل ترتيب suffix=5؛ المواد المجاورة (22 مكرراً (ب) و(ج) المفترضة من تسمية (د)) غير موجودة فى القاعدة.$c257$);

DO $m257$
DECLARE
  v_law uuid;
  v_title text;
  r record;
  v_art uuid;
  v_artbody text;
  v_cur record;
  v_nur int;
  v_maxv int;
  v_applied int := 0;
  v_skipped int := 0;
  v_added int := 0;
  v_cnt int;
BEGIN
  IF (SELECT count(*) FROM m257_amend WHERE md5(new_body) <> new_md5) <> 0
     OR (SELECT count(*) FROM m257_new WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[257] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m257_amend) <> 6 OR (SELECT count(*) FROM m257_new) <> 8
     OR (SELECT sum(char_length(new_body)) FROM m257_amend) + (SELECT sum(char_length(body)) FROM m257_new) <> 13923 THEN
    RAISE EXCEPTION '[257] عدد الصفوف أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=3 AND law_year=2005 AND kind='law';
  IF v_law IS NULL THEN
    RAISE EXCEPTION '[257] القانون 3/2005 غير موجود: يجب تشغيل 225 و256 أولاً';
  END IF;
  IF v_title NOT LIKE '%المنافسة%' THEN
    RAISE EXCEPTION '[257] مستند آخر برقم 3 لسنة 2005 (%): لا يُطبَّق التعديل عليه', v_title;
  END IF;

  -- ===== المواد المعدلة =====
  FOR r IN SELECT * FROM m257_amend ORDER BY article_no, suffix LOOP
    SELECT a.id, a.body INTO v_art, v_artbody FROM articles a WHERE a.law_id = v_law AND a.article_no = r.article_no AND a.article_suffix_order = r.suffix;
    IF v_art IS NULL THEN
      RAISE EXCEPTION '[257] المادة % (suffix %) غير موجودة: يجب تشغيل 225 و256 أولاً', r.article_no, r.suffix;
    END IF;
    SELECT count(*) INTO v_nur FROM article_versions WHERE article_id = v_art AND effective_to IS NULL;
    IF v_nur <> 1 THEN
      RAISE EXCEPTION '[257] المادة % (suffix %): % نسخة حالية بدل 1', r.article_no, r.suffix, v_nur;
    END IF;
    SELECT * INTO v_cur FROM article_versions WHERE article_id = v_art AND effective_to IS NULL;
    SELECT max(version_no) INTO v_maxv FROM article_versions WHERE article_id = v_art;

    IF EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = v_art AND v.body = r.new_body AND v.amended_by_law_no = 175 AND v.amended_by_law_year = 2022) THEN
      v_skipped := v_skipped + 1;      -- طُبق من قبل (وقد يكون عُدل بعده بقانون لاحق)
    ELSIF v_cur.status = 'active' AND md5(v_cur.body) = r.pre_md5 AND md5(v_artbody) = r.pre_md5 THEN
      UPDATE article_versions SET status = 'amended', effective_to = DATE '2022-12-29' WHERE id = v_cur.id;
      INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
      VALUES (v_art, v_maxv + 1, r.new_body, DATE '2022-12-30', NULL, 'active', 175, 2022, r.note);
      UPDATE articles SET body = r.new_body, updated_at = now() WHERE id = v_art;
      v_applied := v_applied + 1;
    ELSE
      RAISE EXCEPTION '[257] نص المادة % (suffix %) لا يطابق نص ما بعد 225 و256: لا يُطبَّق التعديل', r.article_no, r.suffix;
    END IF;
  END LOOP;

  -- ===== المواد المضافة =====
  FOR r IN SELECT * FROM m257_new ORDER BY article_no, suffix LOOP
    SELECT a.id INTO v_art FROM articles a WHERE a.law_id = v_law AND a.article_no = r.article_no AND a.article_suffix_order = r.suffix;
    IF v_art IS NULL THEN
      INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
      VALUES (v_law, r.article_no, r.suffix, r.loc, r.body) RETURNING id INTO v_art;
      INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
      VALUES (v_art, 1, r.body, DATE '2022-12-30', NULL, 'active', 175, 2022, r.note);
      v_added := v_added + 1;
    ELSE
      IF NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = v_art AND v.version_no = 1 AND v.body = r.body AND v.amended_by_law_no = 175 AND v.amended_by_law_year = 2022) THEN
        RAISE EXCEPTION '[257] المادة % (suffix %) موجودة بنص مختلف عن نص 175/2022', r.article_no, r.suffix;
      END IF;
      v_skipped := v_skipped + 1;
    END IF;
  END LOOP;

  -- ===== ملاحظات النسخ الأولى: لم يعد التعديل «غير مرفوع» =====
  UPDATE article_versions av SET change_note = CASE
      WHEN EXISTS (SELECT 1 FROM article_versions x WHERE x.article_id = av.article_id AND x.version_no = 3 AND x.amended_by_law_no = 175) THEN $b257$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005، سرى حتى 22/6/2008 وعدلته المادة المقابلة من القانون 190 لسنة 2008 (انظر النسخة 2)، ثم عدلها القانون 175 لسنة 2022 (انظر النسخة 3)$b257$
      ELSE $a257$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005، سرى حتى 22/6/2008 وعدلته المادة المقابلة من القانون 190 لسنة 2008 (انظر النسخة 2)$a257$ END
    FROM articles a
   WHERE a.id = av.article_id AND a.law_id = v_law AND av.version_no = 1 AND av.status = 'amended'
     AND av.change_note = $o257$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005، سرى حتى 22/6/2008 وعدلته المادة المقابلة من القانون 190 لسنة 2008 (انظر النسخة 2). عدل القانون لاحقا بالقانون 175 لسنة 2022 ونصه لم يرفع بعد$o257$;
  UPDATE article_versions av SET change_note = CASE WHEN av.status = 'amended' THEN $z257$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005، سرى حتى 29/12/2022 وعدله القانون 175 لسنة 2022 (انظر النسخة 2)$z257$ ELSE $k257$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005، وهذه المادة لم يمسها القانونان 190 لسنة 2008 و175 لسنة 2022 (وهما التعديلان المرفوعان فى المشروع)$k257$ END
    FROM articles a
   WHERE a.id = av.article_id AND a.law_id = v_law AND av.version_no = 1
     AND av.change_note = $o257$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005، وهذه المادة لم يمسها القانون 190 لسنة 2008. عدل القانون لاحقا بالقانون 175 لسنة 2022 (جوهرى بحسب ملاحظات المشروع) ونصه لم يرفع بعد، فقد لا يطابق هذا النص الصيغة النافذة حاليا$o257$;

  -- ===== سجل القانون =====
  UPDATE laws SET
    last_amended_at = DATE '2022-12-30',
    title = $t257$القانون رقم 3 لسنة 2005 بإصدار قانون حماية المنافسة ومنع الممارسات الاحتكارية (النص الأصلى المنشور فى 15/2/2005 معدلاً بالقانونين رقم 190 لسنة 2008 ورقم 175 لسنة 2022)$t257$
   WHERE id = v_law AND (last_amended_at IS NULL OR last_amended_at < DATE '2022-12-30');

  -- ===== التحقق النهائى =====
  SELECT count(*) INTO v_cnt FROM articles WHERE law_id = v_law;
  IF v_cnt < 40 THEN
    RAISE EXCEPTION '[257] عدد صفوف القانون % أقل من 40', v_cnt;
  END IF;
  SELECT count(*) INTO v_cnt FROM articles a WHERE a.law_id = v_law
     AND (SELECT count(*) FROM article_versions v WHERE v.article_id = a.id AND v.effective_to IS NULL) <> 1;
  IF v_cnt <> 0 THEN
    RAISE EXCEPTION '[257] % مادة بلا نسخة حالية وحيدة', v_cnt;
  END IF;
  SELECT count(*) INTO v_cnt FROM articles a JOIN article_versions v ON v.article_id = a.id AND v.effective_to IS NULL
   WHERE a.law_id = v_law AND a.body <> v.body;
  IF v_cnt <> 0 THEN
    RAISE EXCEPTION '[257] % مادة نصها لا يطابق نسختها الحالية', v_cnt;
  END IF;
  SELECT count(*) INTO v_cnt FROM m257_amend m JOIN articles a ON a.law_id = v_law AND a.article_no = m.article_no AND a.article_suffix_order = m.suffix
    JOIN article_versions v ON v.article_id = a.id AND v.body = m.new_body AND v.amended_by_law_no = 175 AND v.effective_from = DATE '2022-12-30'
         AND ((v.effective_to IS NULL AND v.status = 'active' AND a.body = m.new_body) OR v.status = 'amended')
    JOIN article_versions p ON p.article_id = a.id AND p.version_no = v.version_no - 1 AND p.status = 'amended' AND p.effective_to = DATE '2022-12-29' AND md5(p.body) = m.pre_md5;
  IF v_cnt <> 6 THEN
    RAISE EXCEPTION '[257] المواد المعدلة المتحقق منها % بدل 6', v_cnt;
  END IF;
  SELECT count(*) INTO v_cnt FROM m257_new m JOIN articles a ON a.law_id = v_law AND a.article_no = m.article_no AND a.article_suffix_order = m.suffix
    JOIN article_versions v ON v.article_id = a.id AND v.version_no = 1 AND v.body = m.body AND v.amended_by_law_no = 175;
  IF v_cnt <> 8 THEN
    RAISE EXCEPTION '[257] المواد المضافة المتحقق منها % بدل 8', v_cnt;
  END IF;
  RAISE NOTICE '[257] تعديل 175/2022 على 3/2005: مواد معدلة=%, مضافة=%, متخطاة=%', v_applied, v_added, v_skipped;
END
$m257$;
